 const memoryStorage=Object.create(null);const appStorage={getItem(key){try{const value=globalThis.localStorage.getItem(key);return value===null?(memoryStorage[key]??null):value}catch{return memoryStorage[key]??null}},setItem(key,value){memoryStorage[key]=String(value);try{globalThis.localStorage.setItem(key,String(value))}catch{}},removeItem(key){delete memoryStorage[key];try{globalThis.localStorage.removeItem(key)}catch{}}};
  const products=[{name:'Everyday Serum',emoji:'🧴',thumb:'',sold:2840,revenue:42600,views:68200,likes:4210,rate:4.2,status:'On track',channels:{LinkedIn:610,Instagram:1360,Google:520,YouTube:350}},{name:'Cloud Cream',emoji:'☁️',thumb:'blue',sold:1920,revenue:32640,views:51900,likes:3870,rate:3.7,status:'On track',channels:{LinkedIn:310,Instagram:930,Google:410,YouTube:270}},{name:'Glow Cleanser',emoji:'🫧',thumb:'pink',sold:1480,revenue:20720,views:37400,likes:2160,rate:3.1,status:'Needs focus',channels:{LinkedIn:250,Instagram:680,Google:320,YouTube:230}},{name:'Daily SPF 50',emoji:'☀️',thumb:'green',sold:1260,revenue:30240,views:41500,likes:3280,rate:3.0,status:'On track',channels:{LinkedIn:220,Instagram:590,Google:260,YouTube:190}}];
  const channels=[{name:'LinkedIn',class:'li',mark:'in',sales:1390,revenue:27800,views:162400,likes:8430,change:18.4},{name:'Instagram',class:'ig',mark:'◎',sales:3560,revenue:71200,views:284600,likes:28400,change:26.2},{name:'Google',class:'google',mark:'G',sales:1510,revenue:30200,views:128300,likes:12700,change:8.7},{name:'YouTube',class:'youtube',mark:'Yt',sales:2040,revenue:61200,views:86400,likes:15400,change:12.1}];
  const fmt=n=>new Intl.NumberFormat('en-US').format(n); const money=n=>'$'+new Intl.NumberFormat('en-US').format(n);
  const currentDisplayName=()=>appStorage.getItem('mw-display-name')||'Jordan Davis';
  const state={page:'overview',product:'All products',channel:'All channels',period:'Last 30 days',authMode:'signin'};
  const content=document.getElementById('content');
  function filteredProducts(){return state.product==='All products'?products:products.filter(p=>p.name===state.product)}
  function metricData(){let ps=filteredProducts(), names=ps.map(p=>p.name);let cs=channels.filter(c=>state.channel==='All channels'||c.name===state.channel);let sold=ps.reduce((a,p)=>a+p.sold,0),revenue=ps.reduce((a,p)=>a+p.revenue,0),views=ps.reduce((a,p)=>a+p.views,0),likes=ps.reduce((a,p)=>a+p.likes,0);if(state.channel!=='All channels'){const c=channels.find(x=>x.name===state.channel);const total=channels.reduce((a,x)=>a+x.sales,0),ratio=c.sales/total;sold=Math.round(sold*ratio);revenue=Math.round(revenue*ratio);views=Math.round(views*ratio);likes=Math.round(likes*ratio)}return{ps,cs,sold,revenue,views,likes}}
  function filters(){return `<div class="filters"><span class="filter-label">Showing</span><select class="select" id="productFilter"><option>All products</option>${products.map(p=>`<option ${state.product===p.name?'selected':''}>${p.name}</option>`).join('')}</select><select class="select" id="channelFilter"><option>All channels</option>${channels.map(c=>`<option ${state.channel===c.name?'selected':''}>${c.name}</option>`).join('')}</select><select class="select" id="periodFilter"><option>Last 30 days</option><option ${state.period==='Last 7 days'?'selected':''}>Last 7 days</option><option ${state.period==='This quarter'?'selected':''}>This quarter</option></select></div>`}
  function stat(label,value,foot,icon,trend='positive'){return `<div class="card stat"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-foot"><span class="${trend}">${foot.split(' ')[0]}</span>${foot.split(' ').slice(1).join(' ')}</div></div>`}
  function chart(){return `<div class="chart-wrap"><div class="tooltip">Oct 22 <b>$8,420</b><span style="color:#b8d78e">↑ 18.6%</span></div><svg class="chart" viewBox="0 0 650 190" preserveAspectRatio="none"><defs><linearGradient id="fade" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#7eae72" stop-opacity=".22"/><stop offset="1" stop-color="#7eae72" stop-opacity="0"/></linearGradient></defs>${[20,60,100,140,180].map(y=>`<line x1="0" y1="${y}" x2="650" y2="${y}" class="gridline"/>`).join('')}<path class="area-main" d="M0 145 C35 135 39 112 72 122 S120 145 145 105 S195 117 218 82 S265 110 290 93 S335 72 362 92 S405 54 436 70 S470 96 502 48 S545 67 572 39 S616 55 650 22 L650 180 L0 180Z"/><path class="line-sub" d="M0 159 C40 155 48 142 78 150 S122 127 145 136 S180 118 212 128 S252 114 283 119 S322 96 355 112 S401 95 432 101 S468 83 498 93 S541 73 572 82 S620 66 650 72"/><path class="line-main" d="M0 145 C35 135 39 112 72 122 S120 145 145 105 S195 117 218 82 S265 110 290 93 S335 72 362 92 S405 54 436 70 S470 96 502 48 S545 67 572 39 S616 55 650 22"/><circle class="chart-dot" cx="502" cy="48" r="4"/>${['Oct 1','Oct 5','Oct 9','Oct 13','Oct 17','Oct 21','Oct 25','Oct 29'].map((x,i)=>`<text class="axis-label" x="${i*92}" y="188">${x}</text>`).join('')}<text class="axis-label" x="-32" y="22">$12k</text><text class="axis-label" x="-32" y="62">$9k</text><text class="axis-label" x="-32" y="102">$6k</text><text class="axis-label" x="-32" y="142">$3k</text></svg></div>`}
  function productRows(ps){return ps.map(p=>`<tr><td><div class="product"><span class="product-thumb ${p.thumb}">${p.emoji}</span>${p.name}</div></td><td>${fmt(p.sold)}</td><td>${money(p.revenue)}</td><td>${fmt(p.views)}</td><td>${p.rate}%</td><td><span class="badge ${p.status==='Needs focus'?'watch':''}">${p.status}</span></td></tr>`).join('')}
  function recs(){return `<div class="recommend"><span class="rec-num">01</span><div><b>Put your best performer to work</b><p>Instagram drives 42% of sales. Reallocate $1,200 from lower-performing Google placements.</p><span class="tag">Potential +$4.8k revenue</span></div></div><div class="recommend"><span class="rec-num">02</span><div><b>Refresh the Glow Cleanser story</b><p>Its conversion rate trails the portfolio by 1.1 points. Test a social proof creative this week.</p><span class="tag">Conversion opportunity</span></div></div><div class="recommend"><span class="rec-num">03</span><div><b>Close the monthly target gap</b><p>Increase LinkedIn spend by 15% on Everyday Serum to make up the 12% shortfall.</p><span class="tag">2 weeks remaining</span></div></div>`}
  function overview(){const d=metricData();return `<div class="heading-row"><div><div class="eyebrow">TUESDAY, OCTOBER 29, 2026</div><h1>Good afternoon, Jordan <span style="font-size:22px">✳</span></h1><p>Here’s what’s happening across your marketing today.</p></div><div class="heading-actions">${filters()}<button class="btn primary" id="exportBtn">↓ <span>Export report</span></button></div></div><div class="stats">${stat('Total revenue',money(d.revenue),'↑ 18.6% vs. previous period','↗')}${stat('Products sold',fmt(d.sold),'↑ 12.3% vs. previous period','▧')}${stat('Total views',fmt(d.views),'↑ 24.8% vs. previous period','◉')}${stat('Engagement',fmt(d.likes),'↑ 8.2% vs. previous period','♡')}</div><div class="grid-main"><section class="card panel"><div class="panel-head"><div><h2>Performance over time</h2><div class="panel-sub">Revenue and engagement across all channels</div></div><div class="legend"><span><i></i>Revenue</span><span><i></i>Engagement</span></div></div>${chart()}</section><section class="card panel channels-panel"><div class="panel-head"><div><h2>Channel performance</h2><div class="panel-sub">Revenue contribution by platform</div></div><button class="btn" data-goto="channels" style="padding:7px 9px;font-size:10px">View all →</button></div><div class="channel-list">${d.cs.map(c=>`<div class="channel-row"><div class="channel-mark ${c.class}">${c.mark}</div><div><div class="channel-name">${c.name}</div><div class="channel-detail">${fmt(c.views)} views · ${fmt(c.sales)} sold</div><div class="progress"><i style="width:${Math.round(c.revenue/Math.max(...d.cs.map(x=>x.revenue))*100)}%"></i></div></div><div class="channel-value">${money(c.revenue)}<small>↑ ${c.change}%</small></div></div>`).join('')}</div></section></div><div class="grid-lower"><section class="card table-panel"><div class="table-head"><div><h2>Product performance</h2><div class="panel-sub">A closer look at what’s selling</div></div><button class="btn" data-goto="products" style="padding:7px 9px;font-size:10px">All products →</button></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Units sold</th><th>Revenue</th><th>Views</th><th>Conv. rate</th><th>Status</th></tr></thead><tbody>${productRows(d.ps)}</tbody></table></div></section><section><div class="card goal-card"><div class="goal-top"><h2>Monthly revenue goal</h2><span class="goal-chip">October</span></div><div class="goal-number"><strong>${money(d.revenue)}</strong><span>of $240,000</span></div><div class="goal-bar"><i style="width:${Math.min(100,d.revenue/2400)}%"></i></div><div class="goal-meta"><span>${Math.round(d.revenue/2400)}% achieved</span><span>$66,800 to go</span></div><div class="goal-bottom"><span>Projected month-end</span><b>$258,400 <span class="positive">↑ 8%</span></b></div></div><div class="card panel" style="margin-top:12px"><div class="panel-head"><div><h2>Smart recommendations</h2><div class="panel-sub">Actions to help you hit your goals</div></div><span class="spark">✧</span></div>${recs()}</div></section></div>`}
  function channelsPage(){return `<div class="heading-row"><div><div class="eyebrow">YOUR DISTRIBUTION MIX</div><h1>Channel performance</h1><p>See which platforms turn attention into sales.</p></div><div class="heading-actions">${filters()}</div></div><div class="stats">${stat('Best revenue channel','$71,200','↑ 26.2% Instagram','◎')}${stat('Most views','284,600','↑ 31.4% Instagram','◉')}${stat('Most engaged','28,400','↑ 16.8% Instagram','♡')}${stat('Channel sales','8,500','↑ 14.2% vs. last month','▧')}</div><div class="card panel"><div class="panel-head"><div><h2>Platform comparison</h2><div class="panel-sub">Performance across your connected channels</div></div></div><div class="table-wrap"><table><thead><tr><th>Channel</th><th>Revenue</th><th>Products sold</th><th>Views</th><th>Likes</th><th>Change</th><th>Share of revenue</th></tr></thead><tbody>${channels.map(c=>`<tr><td><div class="product"><span class="channel-mark ${c.class}">${c.mark}</span>${c.name}</div></td><td>${money(c.revenue)}</td><td>${fmt(c.sales)}</td><td>${fmt(c.views)}</td><td>${fmt(c.likes)}</td><td class="growth">↑ ${c.change}%</td><td><div style="display:flex;align-items:center;gap:8px"><div class="progress" style="width:70px;margin:0"><i style="width:${Math.round(c.revenue/712)}%"></i></div>${Math.round(c.revenue/1910)}%</div></td></tr>`).join('')}</tbody></table></div></div><div class="grid-main" style="margin-top:16px"><div class="card panel"><div class="panel-head"><div><h2>Channel insights</h2><div class="panel-sub">What the numbers tell you</div></div></div>${recs()}</div><div class="card panel"><h2>Top channel this month</h2><div class="channel-mark ig" style="width:42px;height:42px;margin:18px 0 10px;font-size:20px">◎</div><div style="font:700 24px Manrope">Instagram</div><p class="panel-sub" style="line-height:1.7">Leading on revenue, reach, and engagement. Your strongest channel for product discovery and direct conversions.</p><div class="goal-bottom"><span>Revenue contribution</span><b>37.3%</b></div></div></div>`}
  function productsPage(){return `<div class="heading-row"><div><div class="eyebrow">PORTFOLIO OVERVIEW</div><h1>Product performance</h1><p>Know what’s resonating and where to invest next.</p></div><div class="heading-actions">${filters()}<button class="btn primary" id="addProduct">＋ Add product</button></div></div><div class="stats">${stat('Portfolio revenue','$154,200','↑ 18.6% vs. previous period','↗')}${stat('Total units sold','7,500','↑ 12.3% vs. previous period','▧')}${stat('Average conversion','3.5%','↑ 0.4 pts vs. previous period','◎')}${stat('Best seller','Everyday Serum','↑ 19.4% unit sales','✳')}</div><div class="card table-panel"><div class="table-head"><div><h2>All products</h2><div class="panel-sub">Product performance across every channel</div></div><button class="btn" id="sortProducts">↕ Sort by revenue</button></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Units sold</th><th>Revenue</th><th>Views</th><th>Likes</th><th>Conv. rate</th><th>Status</th></tr></thead><tbody>${filteredProducts().map(p=>`<tr><td><div class="product"><span class="product-thumb ${p.thumb}">${p.emoji}</span>${p.name}</div></td><td>${fmt(p.sold)}</td><td>${money(p.revenue)}</td><td>${fmt(p.views)}</td><td>${fmt(p.likes)}</td><td>${p.rate}%</td><td><span class="badge ${p.status==='Needs focus'?'watch':''}">${p.status}</span></td></tr>`).join('')}</tbody></table></div></div><div class="grid-main" style="margin-top:16px"><div class="card panel"><div class="panel-head"><div><h2>Product × channel sales</h2><div class="panel-sub">Where each product is winning</div></div></div><div class="table-wrap"><table><thead><tr><th>Product</th>${channels.map(c=>`<th>${c.name}</th>`).join('')}</tr></thead><tbody>${products.map(p=>`<tr><td><div class="product"><span class="product-thumb ${p.thumb}">${p.emoji}</span>${p.name}</div></td>${channels.map(c=>`<td>${fmt(p.channels[c.name])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div><div class="card panel"><div class="panel-head"><div><h2>Product spotlight</h2><div class="panel-sub">Everyday Serum is your top seller</div></div><span class="spark">✧</span></div><p style="font-size:11px;line-height:1.65;color:#718077">LinkedIn brings 610 sales for this product. Expand the current audience with a customer story creative and a retargeting campaign for viewers who visited the product page.</p><span class="badge">Top recommendation</span></div></div>`}
  function goalsPage(){return `<div class="heading-row"><div><div class="eyebrow">PLAN AGAINST PERFORMANCE</div><h1>Goals &amp; targets</h1><p>Track progress and adjust your plan before the month ends.</p></div><button class="btn primary" id="editGoal">✎ Edit goals</button></div><div class="stats">${stat('Revenue target','$240,000','October company goal','◎')}${stat('Revenue so far','$173,200','↑ 18.6% vs. previous period','↗')}${stat('Target achieved','72%','$66,800 remaining','◫','negative')}${stat('Forecast at current pace','$258,400','↑ 8% above target','✧')}</div><div class="grid-main"><section class="card panel"><div class="panel-head"><div><h2>Company goal progress</h2><div class="panel-sub">October 1 – October 31, 2026</div></div><span class="goal-chip">12 days left</span></div><div class="goal-number"><strong>$173,200</strong><span>of $240,000 target</span></div><div class="goal-bar"><i style="width:72%"></i></div><div class="goal-meta"><span>72% achieved</span><span>Target: $240,000</span></div><div style="height:24px"></div><div class="table-wrap"><table><thead><tr><th>Channel</th><th>Target</th><th>Actual</th><th>Progress</th><th>Gap</th></tr></thead><tbody>${[['LinkedIn',40000,27800],['Instagram',65000,71200],['Google',42000,30200],['YouTube',55000,61200]].map(([n,t,a])=>`<tr><td><b>${n}</b></td><td>${money(t)}</td><td>${money(a)}</td><td>${Math.round(a/t*100)}%</td><td style="color:${a>=t?'#398357':'#bd7b44'}">${a>=t?'+'+money(a-t):money(t-a)}</td></tr>`).join('')}</tbody></table></div></section><section class="card panel"><div class="panel-head"><div><h2>Recommended next steps</h2><div class="panel-sub">Your clearest path to the target</div></div><span class="spark">✧</span></div>${recs()}</section></div><div class="card panel" style="margin-top:16px"><h2>Goal planning notes</h2><p style="font-size:11px;line-height:1.7;color:#76847b">At the current pace, the team is forecast to finish <b style="color:#2e6943">$18,400 above target</b>. Instagram and YouTube have exceeded their allocated revenue targets. LinkedIn is $12,200 behind its target; prioritise the Everyday Serum campaign and retargeting to close the gap.</p></div>`}
  function campaignsPage(){return `<div class="heading-row"><div><div class="eyebrow">PLAN, PUBLISH, GROW</div><h1>Campaigns</h1><p>Coordinate your campaigns and see how they perform.</p></div><button class="btn primary" id="newCampaign">＋ New campaign</button></div><div class="subnav"><button class="active">All campaigns <span class="count">8</span></button><button>Active <span class="count">4</span></button><button>Drafts <span class="count">2</span></button><button>Completed <span class="count">2</span></button></div><div class="campaign-cards">${[['Autumn Glow Launch','Active','Oct 10 – Nov 05','Instagram · LinkedIn','$18,420','↑ 24.8%'],['Everyday Essentials','Active','Oct 14 – Nov 14','YouTube · Instagram','$12,760','↑ 18.2%'],['Your Skin, Your Story','Active','Oct 20 – Nov 08','LinkedIn · Google','$9,840','↑ 12.6%'],['Cloud Nine Retargeting','Active','Oct 23 – Nov 06','Instagram · YouTube','$7,200','↑ 9.4%'],['Holiday Preview','Draft','Nov 01 – Nov 30','All channels','—','Not started'],['Clean Routine Refresh','Draft','Nov 05 – Nov 25','Instagram · LinkedIn','—','Not started']].map((x,i)=>`<article class="card campaign-card"><div style="display:flex;justify-content:space-between"><span class="badge ${x[1]==='Draft'?'watch':''}">${x[1]}</span><span style="color:#98a29c">···</span></div><h3>${x[0]}</h3><p>${i<4?'Across your product range, build awareness and drive purchases with coordinated creative.':'Plan your upcoming campaign and coordinate content across channels.'}</p><div class="campaign-meta"><span>${x[2]}</span><b>${x[3]}</b></div><div class="campaign-meta" style="border:0;padding-top:8px;margin-top:0"><span>${i<4?'Revenue to date':'Status'}</span><b>${x[4]} <span class="growth">${x[5]}</span></b></div></article>`).join('')}</div>`}
  function insightsPage(){return `<div class="heading-row"><div><div class="eyebrow">YOUR NEXT BEST MOVE</div><h1>Insights &amp; recommendations</h1><p>Turn your latest performance into clear, practical actions.</p></div><select class="select"><option>All recommendations</option><option>Revenue growth</option><option>Campaign optimization</option></select></div><div class="grid-main"><div class="card panel"><div class="panel-head"><div><h2>Recommended for you</h2><div class="panel-sub">Prioritized by projected impact</div></div><span class="spark">✧</span></div>${recs()}<div class="recommend"><span class="rec-num">04</span><div><b>Post when your audience is online</b><p>Instagram engagement peaks between 6–8 PM on weekdays. Schedule the next product reveal for Wednesday evening.</p><span class="tag">Engagement opportunity</span></div></div></div><div class="card panel"><div class="panel-head"><div><h2>What’s working</h2><div class="panel-sub">Patterns in your performance data</div></div></div><div class="insight"><div class="insight-head"><span class="spark">↗</span><b>Social proof is converting</b></div><p>Customer testimonial posts generated 2.4× more purchases than product-only creative this month.</p></div><div class="insight"><div class="insight-head"><span class="spark">◎</span><b>Instagram is your growth engine</b></div><p>It leads all channels in views, engagement, and sales. Keep creative fresh to sustain momentum.</p></div><div class="insight"><div class="insight-head"><span class="spark">◷</span><b>Midweek launches perform best</b></div><p>Wednesday campaigns see 31% higher first-day click-through than Monday launches.</p></div></div></div>`}
  function audiencePage(){return `<div class="heading-row"><div><div class="eyebrow">KNOW WHO YOU’RE REACHING</div><h1>Audience</h1><p>Understand who engages with your brand and what moves them.</p></div><button class="btn">↓ Export audience</button></div><div class="stats">${stat('Total audience','48,290','↑ 8.4% this month','♧')}${stat('Returning customers','34.8%','↑ 3.2 pts this month','↺')}${stat('Avg. order value','$48.60','↑ 6.1% this month','＄')}${stat('Customer lifetime value','$182','↑ 11.2% this month','♡')}</div><div class="grid-main"><div class="card panel"><div class="panel-head"><div><h2>Audience segments</h2><div class="panel-sub">A simple view of your customer mix</div></div></div>${[['First-time buyers',36,'2,740 customers'],['Repeat customers',29,'2,205 customers'],['Engaged followers',23,'1,748 customers'],['At-risk customers',12,'912 customers']].map(x=>`<div style="margin:18px 0"><div style="display:flex;justify-content:space-between;font-size:11px"><b>${x[0]}</b><span style="color:#87938b">${x[2]} · ${x[1]}%</span></div><div class="progress" style="height:7px;margin-top:8px"><i style="width:${x[1]}%"></i></div></div>`).join('')}</div><div class="card panel"><h2>Audience opportunity</h2><p style="font-size:11px;line-height:1.65;color:#758279;margin-top:12px">Your returning customers account for 29% of customers but drive 46% of revenue. A thoughtful replenishment email or loyalty offer could bring more customers back.</p><div class="insight" style="margin-top:15px"><div class="insight-head"><span class="spark">✧</span><b>Try a replenishment reminder</b></div><p>Reach customers 30–45 days after their first Everyday Serum purchase.</p></div></div></div><div class="card panel"><div class="panel-head"><div><h2>Audience by channel</h2><div class="panel-sub">Reach and engagement across connected platforms</div></div></div><div class="table-wrap"><table><thead><tr><th>Channel</th><th>Followers / subscribers</th><th>Growth this month</th><th>Engagement rate</th><th>Top audience</th></tr></thead><tbody><tr><td><b>Instagram</b></td><td>28,400</td><td class="growth">↑ 11.8%</td><td>4.8%</td><td>25–34 · 62%</td></tr><tr><td><b>LinkedIn</b></td><td>8,320</td><td class="growth">↑ 6.4%</td><td>3.2%</td><td>Professionals · 71%</td></tr><tr><td><b>Google</b></td><td>11,570</td><td class="growth">↑ 3.1%</td><td>2.7%</td><td>35–44 · 48%</td></tr></tbody></table></div></div>`}
  function reportsPage(){return `<div class="heading-row"><div><div class="eyebrow">CLEAR VIEWS FOR YOUR TEAM</div><h1>Reports</h1><p>Share your progress with the people who move your business forward.</p></div><button class="btn primary" id="createReport">＋ Create report</button></div><div class="card panel"><div class="panel-head"><div><h2>Recent reports</h2><div class="panel-sub">Saved reports and performance snapshots</div></div><select class="select"><option>All reports</option><option>Shared with me</option></select></div>${[['October marketing overview','Oct 29, 2026','Monthly summary · All channels','JD'],['Social channel performance','Oct 27, 2026','Channel comparison · 30 days','JD'],['Product sales snapshot','Oct 24, 2026','Product performance · 30 days','AM'],['Autumn Glow campaign','Oct 22, 2026','Campaign report · Oct 10–22','JD']].map(x=>`<div class="report-row"><span class="report-icon">▤</span><div><h3>${x[0]}</h3><p>${x[2]} · Updated ${x[1]}</p></div><span style="font-size:10px;color:#87938b">${x[3]} · Shared</span><button class="btn">View report →</button></div>`).join('')}</div>`}
  function settingsPage(){return `<div class="heading-row"><div><div class="eyebrow">MAKE IT YOURS</div><h1>Settings</h1><p>Manage your workspace, account, and connected channels.</p></div></div><div class="subnav"><button class="active">Workspace</button><button>My profile</button><button>Integrations</button><button>Notifications</button></div><div class="settings-grid"><div class="card panel"><div class="panel-head"><div><h2>Workspace preferences</h2><div class="panel-sub">Manage how your team uses Marketwise.</div></div></div><div class="setting-row"><div><b>Workspace name</b><br><span>Northstar Studio</span></div><button class="btn">Edit</button></div><div class="setting-row"><div><b>Reporting currency</b><br><span>USD — US Dollar</span></div><button class="btn">Change</button></div><div class="setting-row"><div><b>Week starts on</b><br><span>Monday</span></div><button class="btn">Change</button></div></div><div class="card panel"><div class="panel-head"><div><h2>Connected channels</h2><div class="panel-sub">Your reporting connections</div></div></div>${channels.map(c=>`<div class="setting-row"><div style="display:flex;align-items:center;gap:9px"><span class="channel-mark ${c.class}">${c.mark}</span><div><b>${c.name}</b><br><span>Last synced 18 min ago</span></div></div><span class="badge">Connected</span></div>`).join('')}<button class="btn" style="margin-top:13px">＋ Connect a channel</button></div></div>`}
  const pages={overview,campaigns:campaignsPage,products:productsPage,channels:channelsPage,audience:audiencePage,goals:goalsPage,insights:insightsPage,reports:reportsPage,settings:settingsPage}; const titles={overview:'Overview',campaigns:'Campaigns',products:'Products',channels:'Channels',audience:'Audience','goals':'Goals & targets',insights:'Insights',reports:'Reports',settings:'Settings'};
  function render(){document.getElementById('crumb').textContent=titles[state.page];content.innerHTML=pages[state.page]();document.querySelectorAll('#nav button[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));bindPageControls();const name=currentDisplayName();const profileName=document.querySelector('.profile b');const profileAvatar=document.querySelector('.profile .avatar');const topAvatar=document.querySelector('.top-avatar');if(profileName)profileName.textContent=name;if(profileAvatar)profileAvatar.textContent=name.split(/\\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();if(topAvatar)topAvatar.textContent=name.split(/\\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase()}
  function bindPageControls(){['productFilter','channelFilter','periodFilter'].forEach(id=>{const el=document.getElementById(id);if(el)el.addEventListener('change',()=>{if(id==='productFilter')state.product=el.value;if(id==='channelFilter')state.channel=el.value;if(id==='periodFilter')state.period=el.value;render()})});document.querySelectorAll('[data-goto]').forEach(b=>b.addEventListener('click',()=>goto(b.dataset.goto)));const exportBtn=document.getElementById('exportBtn');if(exportBtn)exportBtn.addEventListener('click',()=>{const d=metricData();const csv='Metric,Value\nRevenue,'+d.revenue+'\nUnits sold,'+d.sold+'\nViews,'+d.views+'\nEngagement,'+d.likes+'\n';const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='marketwise-performance.csv';a.click();URL.revokeObjectURL(a.href)});const edit=document.getElementById('editGoal');if(edit)edit.addEventListener('click',()=>{const goal=prompt('Set a monthly revenue goal (USD):','240000');if(goal&&Number(goal)>0){document.querySelector('.goal-number span').textContent='of '+money(Number(goal))}});const add=document.getElementById('addProduct');if(add)add.onclick=()=>alert('Product connection setup is coming soon.');['newCampaign','createReport'].forEach(id=>{const el=document.getElementById(id);if(el)el.onclick=()=>alert('Your workspace is ready to create this. Campaign and report publishing will be available when integrations are connected.')});const sort=document.getElementById('sortProducts');if(sort)sort.onclick=()=>{products.sort((a,b)=>b.revenue-a.revenue);render()}}
  function goto(page){state.page=page;render();document.getElementById('sidebar').classList.remove('open');window.scrollTo(0,0)}
  window.marketwiseGo=goto;
  document.getElementById('nav').addEventListener('click',e=>{const button=e.target.closest('button[data-page]');if(button)goto(button.dataset.page)});document.getElementById('mobileMenu').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));document.getElementById('globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){const q=e.target.value.toLowerCase();const found=products.find(p=>p.name.toLowerCase().includes(q));if(found){state.product=found.name;goto('products')}else if(q.includes('campaign'))goto('campaigns');else if(q.includes('goal'))goto('goals')}});
  let register=false;document.getElementById('authToggle').addEventListener('click',()=>{register=!register;document.getElementById('confirmWrap').classList.toggle('hidden',!register);document.getElementById('authTitle').textContent=register?'Create your account':'Sign in to your workspace';document.getElementById('authDesc').textContent=register?'Start bringing your marketing into focus.':'Pick up where your team left off.';document.getElementById('authEyebrow').textContent=register?'GET STARTED':'WELCOME BACK';document.getElementById('authSubmit').innerHTML=register?'Create account <span>→</span>':'Sign in <span>→</span>';document.getElementById('switchText').textContent=register?'Already have an account?':'New to Marketwise?';document.getElementById('authToggle').textContent=register?'Sign in':'Create an account'});
  document.getElementById('authForm').addEventListener('submit',e=>{e.preventDefault();const user=document.getElementById('username').value.trim(),pass=document.getElementById('password').value;if(register&&document.getElementById('confirmPassword').value!==pass){alert('Your passwords do not match.');return}if(register){appStorage.setItem('mw-user',user);appStorage.setItem('mw-pass',pass)}else{const saved=appStorage.getItem('mw-user');if(saved&&user!==saved){alert('We could not find that account. Check your username or create a new account.');return}if(saved&&appStorage.getItem('mw-pass')!==pass){alert('That password does not match your account.');return}}document.getElementById('auth').classList.add('hidden');document.getElementById('app').classList.remove('hidden');render()});
  if(appStorage.getItem('mw-user')){document.getElementById('username').value=appStorage.getItem('mw-user')}

  // Interactive campaign budget simulator and functional controls.
  const simulatorPage=()=>`<div class="heading-row"><div><div class="eyebrow">PLAN BEFORE YOU SPEND</div><h1>Campaign simulator</h1><p>Explore how budget, channel mix, and conversion rates could affect campaign results.</p></div><button class="btn primary" id="resetSimulation">? Reset simulation</button></div><div class="grid-main"><section class="card panel"><div class="panel-head"><div><h2>Build a scenario</h2><div class="panel-sub">Adjust the inputs to see an instant estimate.</div></div><span class="spark">?</span></div><label class="sim-label" for="simBudget">Campaign budget <b id="budgetValue">$5,000</b></label><input class="sim-range" id="simBudget" type="range" min="500" max="20000" step="250" value="5000"><div class="sim-limits"><span>$500</span><span>$20,000</span></div><label class="sim-label" for="simChannel">Primary channel</label><select class="select sim-select" id="simChannel"><option value="instagram">Instagram</option><option value="linkedin">LinkedIn</option><option value="facebook">Google</option><option value="balanced">Balanced mix</option></select><label class="sim-label" for="simConversion">Estimated conversion rate <b id="conversionValue">3.5%</b></label><input class="sim-range" id="simConversion" type="range" min="1" max="8" step="0.1" value="3.5"><div class="sim-limits"><span>1%</span><span>8%</span></div><label class="sim-label" for="simOrder">Average order value <b id="orderValue">$48</b></label><input class="sim-range" id="simOrder" type="range" min="15" max="150" step="1" value="48"><div class="sim-limits"><span>$15</span><span>$150</span></div></section><section class="card sim-result"><div class="eyebrow">ESTIMATED CAMPAIGN OUTCOME</div><h2 id="simRevenue">$0</h2><p>Projected revenue from this campaign</p><div class="sim-result-grid"><div><span>Estimated purchases</span><b id="simPurchases">0</b></div><div><span>Estimated reach</span><b id="simReach">0</b></div><div><span>Return on ad spend</span><b id="simRoas">0x</b></div><div><span>Net after budget</span><b id="simNet">$0</b></div></div><div class="sim-tip"><span>?</span><div><b id="simAdviceTitle">Scenario insight</b><p id="simAdvice">Increase budget or conversion rate to explore a stronger result.</p></div></div><button class="btn primary" id="saveScenario">Save this scenario</button></section></div><section class="card panel sim-compare"><div class="panel-head"><div><h2>Compare channel scenarios</h2><div class="panel-sub">Illustrative estimates using the same budget and order value.</div></div></div><div class="sim-bars" id="simBars"></div></section><p class="sim-disclaimer">Estimates are illustrative planning figures based on the assumptions above, not guaranteed results. Replace them with your campaign history for better projections.</p>`;
  pages.simulator=simulatorPage; titles.simulator='Campaign simulator';
  const simDefaults={budget:5000,conversion:3.5,order:48,channel:'instagram'};
  function updateSimulator(){const b=document.getElementById('simBudget');if(!b)return;const budget=+b.value,conv=+document.getElementById('simConversion').value,order=+document.getElementById('simOrder').value,channel=document.getElementById('simChannel').value;const cpm={instagram:8.5,linkedin:32,facebook:10,balanced:12}[channel],ctr={instagram:.018,linkedin:.009,facebook:.012,balanced:.014}[channel];const reach=Math.round(budget/cpm*1000),clicks=Math.round(reach*ctr),purchases=Math.round(clicks*conv/100),revenue=purchases*order,roas=revenue/budget;document.getElementById('budgetValue').textContent=money(budget);document.getElementById('conversionValue').textContent=conv.toFixed(1)+'%';document.getElementById('orderValue').textContent=money(order);document.getElementById('simRevenue').textContent=money(revenue);document.getElementById('simPurchases').textContent=fmt(purchases);document.getElementById('simReach').textContent=fmt(reach);document.getElementById('simRoas').textContent=roas.toFixed(2)+'x';document.getElementById('simNet').textContent=money(revenue-budget);const profitable=roas>=1;document.getElementById('simAdviceTitle').textContent=profitable?'Promising scenario':'Room to improve';document.getElementById('simAdvice').textContent=profitable?`At these assumptions, ${channel==='balanced'?'your channel mix':channel} may return ${roas.toFixed(2)}x revenue per ad dollar. Test with a smaller budget before scaling.`:'Try improving the creative or landing page conversion rate, then compare the result before committing budget.';const scenarios=[['Instagram',8.5,.018,'#dc568b'],['LinkedIn',32,.009,'#4b83d3'],['Google',10,.012,'#6474dc'],['Balanced mix',12,.014,'#35aa83']];document.getElementById('simBars').innerHTML=scenarios.map(([name,cpm,clic,color])=>{const rev=Math.round((budget/cpm*1000)*clic*conv/100)*order;return `<div class="sim-bar-row"><span>${name}</span><div class="sim-track"><i style="width:${Math.max(3,Math.min(100,rev/Math.max(1,budget*4)*100))}%;background:${color}"></i></div><b>${money(rev)}</b><small>${(rev/budget).toFixed(2)}x</small></div>`}).join('')}
  document.addEventListener('input',e=>{if(e.target.matches('.sim-range'))updateSimulator()});document.addEventListener('change',e=>{if(e.target.id==='simChannel')updateSimulator()});
  document.addEventListener('click',e=>{const target=e.target.closest('button');if(!target)return;if(target.id==='resetSimulation'){document.getElementById('simBudget').value=simDefaults.budget;document.getElementById('simConversion').value=simDefaults.conversion;document.getElementById('simOrder').value=simDefaults.order;document.getElementById('simChannel').value=simDefaults.channel;updateSimulator();return}if(target.id==='saveScenario'){const message=document.getElementById('simAdvice');target.textContent='? Scenario saved';setTimeout(()=>{if(target.isConnected)target.textContent='Save this scenario'},1600);return}if(target.classList.contains('subnav')||target.closest('.subnav')){const button=target.closest('.subnav button');if(!button)return;const nav=button.closest('.subnav');nav.querySelectorAll('button').forEach(x=>x.classList.remove('active'));button.classList.add('active');if(state.page==='campaigns'){const key=button.textContent.toLowerCase();document.querySelectorAll('.campaign-card').forEach(card=>{const status=card.querySelector('.badge').textContent.toLowerCase();card.classList.toggle('hidden',key.includes('active')&&!key.includes('campaign')&&status!=='active'||key.includes('draft')&&status!=='draft'||key.includes('completed'))})}return}if(target.id==='newCampaign'){const name=prompt('Campaign name:');if(name){alert(`${name} is ready to plan. Connect your marketing channels to publish it.`)}return}if(target.id==='createReport'){alert('Your October marketing overview report is ready to export from the Overview page.');return}if(target.id==='addProduct'){const name=prompt('Product name to add:');if(name){alert(`${name} noted. Connect your store to sync product data.`)}return}if(target.id==='createReport'||target.textContent.includes('View report')){alert('Report preview is ready. Connect your workspace data to generate the full report.');return}if(target.textContent.trim()==='Edit'||target.textContent.trim()==='Change'){const current=target.parentElement.querySelector('span')?.textContent||'';const value=prompt('Update this setting:',current);if(value){target.parentElement.querySelector('span').textContent=value}return}if(target.textContent.includes('Connect a channel')){alert('Choose a channel integration to connect. Integrations will sync live campaign data.');return}if(target.textContent.includes('Export audience')){alert('Audience export is available after connecting a customer data source.');return}if(target.textContent.includes('Create an account')||target.textContent==='Sign in')return;});
  document.addEventListener('click',e=>{if(e.target.closest('.subnav button'))return;});
  const previousRender=render;render=function(){previousRender();if(state.page==='simulator')updateSimulator()};

  const demoAccess=document.getElementById('demoAccess');if(demoAccess)demoAccess.addEventListener('click',()=>{document.getElementById('auth').classList.add('hidden');document.getElementById('app').classList.remove('hidden');render()});

  function plannerPage(){return `<div class="heading-row"><div><div class="eyebrow">PUBLISH WITH A PLAN</div><h1>Content planner</h1><p>Organize upcoming content across social channels and keep campaigns moving.</p></div><button class="btn primary" id="addPost">+ Add content</button></div><div class="planner-toolbar"><div class="subnav"><button class="active" data-plan-filter="all">All content <span class="count">6</span></button><button data-plan-filter="draft">Drafts</button><button data-plan-filter="scheduled">Scheduled</button><button data-plan-filter="published">Published</button></div><div class="filters"><button class="btn" id="prevWeek">? Previous</button><b id="plannerWeek">Oct 26 - Nov 1, 2026</b><button class="btn" id="nextWeek">Next ?</button></div></div><div class="planner-grid" id="plannerGrid">${[['MON','26','Autumn serum story','Instagram','Scheduled','?'],['TUE','27','Founder routine tips','LinkedIn','Draft','in'],['WED','28','Glow Cleanser reveal','Instagram','Scheduled','?'],['THU','29','Customer love carousel','Google','Draft','f'],['FRI','30','Everyday Serum offer','LinkedIn','Scheduled','in'],['SAT','31','Weekend skin ritual','Instagram','Published','?']].map(([day,date,title,channel,status,icon])=>`<article class="card planner-day" data-status="${status.toLowerCase()}"><div class="planner-date"><span>${day}</span><b>${date}</b></div><div class="planner-post"><span class="channel-mark ${channel==='Instagram'?'ig':channel==='LinkedIn'?'li':'google'}">${icon}</span><div><b>${title}</b><small>${channel}</small></div></div><div class="planner-foot"><span class="badge ${status==='Draft'?'watch':''}">${status}</span><button class="btn planner-action">${status==='Published'?'View':status==='Draft'?'Edit':'Mark published'}</button></div></article>`).join('')}</div><div class="card planner-hint"><span class="spark">?</span><div><b>Keep your campaign story consistent</b><p>Schedule product education before promotional posts, then follow up with customer proof.</p></div><button class="btn" onclick="window.marketwiseGo('decision')">Ask AI Decision Studio ?</button></div>`}
  function decisionPage(){return `<div class="heading-row"><div><div class="eyebrow">TURN DATA INTO YOUR NEXT MOVE</div><h1>AI Decision Studio</h1><p>Explore practical marketing actions based on your goal, budget, and channel mix.</p></div><span class="goal-chip">? Decision support</span></div><div class="decision-layout"><section class="card panel"><div class="panel-head"><div><h2>What are you trying to achieve?</h2><div class="panel-sub">Set the context for a tailored plan.</div></div><span class="spark">?</span></div><label class="sim-label" for="decisionGoal">Business objective</label><select class="select decision-input" id="decisionGoal"><option value="sales">Increase product sales</option><option value="awareness">Grow brand awareness</option><option value="launch">Launch a new product</option><option value="retention">Bring customers back</option></select><label class="sim-label" for="decisionBudget">Available campaign budget</label><input class="decision-input" id="decisionBudget" type="number" min="100" step="100" value="5000"><label class="sim-label" for="decisionProduct">Product focus</label><select class="select decision-input" id="decisionProduct">${products.map(p=>`<option>${p.name}</option>`).join('')}</select><label class="sim-label" for="decisionChannel">Preferred channel</label><select class="select decision-input" id="decisionChannel"><option>Recommend best channel</option><option>Instagram</option><option>LinkedIn</option><option>Google</option><option>YouTube</option></select><button class="btn primary" id="generatePlan">? Generate decision brief</button><p class="sim-disclaimer">Suggestions are generated from sample workspace data and should be reviewed before acting.</p></section><section class="card decision-output" id="decisionOutput"><div class="decision-empty"><span>?</span><h2>Your decision brief will appear here</h2><p>Choose an objective and generate a plan to see recommended actions, channel allocation, and success measures.</p></div></section></div><div class="card panel" style="margin-top:16px"><h2>Signals used in this workspace</h2><div class="signal-row"><span class="badge">Instagram leads revenue</span><span class="badge">LinkedIn below target</span><span class="badge">Glow Cleanser needs focus</span><span class="badge">Monthly goal 72% achieved</span></div></div>`}
  function dateReportsPage(){return `<div class="heading-row"><div><div class="eyebrow">REPORTING &amp; DATE RANGE</div><h1>Dates &amp; reports</h1><p>Choose a reporting window and export a focused performance summary.</p></div><button class="btn primary" id="downloadDateReport">? Download CSV</button></div><section class="card panel date-panel"><div class="panel-head"><div><h2>Report date range</h2><div class="panel-sub">Apply a custom range to the summary below.</div></div><select class="select" id="datePreset"><option value="30">Last 30 days</option><option value="7">Last 7 days</option><option value="90">Last 90 days</option><option value="custom">Custom dates</option></select></div><div class="date-inputs"><label>Start date<input id="reportStart" type="date" value="2026-10-01"></label><label>End date<input id="reportEnd" type="date" value="2026-10-29"></label><button class="btn primary" id="applyDateRange">Apply range</button><span id="dateRangeMessage">Showing October 1 - October 29, 2026</span></div></section><div class="stats">${stat('Revenue in range','$173,200','? 18.6% vs. previous period','?')}${stat('Products sold','7,500','? 12.3% vs. previous period','?')}${stat('Views','508,600','? 24.8% vs. previous period','?')}${stat('Engagement','48,710','? 8.2% vs. previous period','?')}</div><div class="card panel"><div class="panel-head"><div><h2>Available reports</h2><div class="panel-sub">Export current sample workspace metrics as CSV.</div></div></div><div class="report-row"><span class="report-icon">?</span><div><h3>Marketing performance summary</h3><p>Revenue, sales, views, engagement, and channel results - date range applied on export</p></div><button class="btn date-export">Download CSV</button></div><div class="report-row"><span class="report-icon">?</span><div><h3>Channel comparison</h3><p>Compare revenue, purchases, views, and engagement by platform</p></div><button class="btn" onclick="window.marketwiseGo('channels')">Open comparison</button></div><div class="report-row"><span class="report-icon">?</span><div><h3>Goals vs. actual</h3><p>Review targets, actual revenue, and remaining gaps by channel</p></div><button class="btn" onclick="window.marketwiseGo('goals')">Open goals</button></div></div>`}
  pages.planner=plannerPage;pages.decision=decisionPage;pages.dateReports=dateReportsPage;titles.planner='Content planner';titles.decision='AI Decision Studio';titles.dateReports='Dates & reports';
  document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='addPost'){const title=prompt('Content title:');if(!title)return;const channel=prompt('Channel (Instagram, LinkedIn, Google):','Instagram')||'Instagram';const card=document.createElement('article');card.className='card planner-day';card.dataset.status='draft';card.innerHTML=`<div class="planner-date"><span>NEW</span><b>-</b></div><div class="planner-post"><span class="channel-mark ig">?</span><div><b>${title.replace(/[<>]/g,'')}</b><small>${channel.replace(/[<>]/g,'')}</small></div></div><div class="planner-foot"><span class="badge watch">Draft</span><button class="btn planner-action">Edit</button></div>`;document.getElementById('plannerGrid').prepend(card);return}if(b.id==='prevWeek'||b.id==='nextWeek'){const label=document.getElementById('plannerWeek');const offset=b.id==='nextWeek'?7:-7;const date=new Date('2026-10-26T12:00:00');date.setDate(date.getDate()+offset);const end=new Date(date);end.setDate(end.getDate()+6);label.textContent=`${date.toLocaleDateString('en-US',{month:'short',day:'numeric'})} - ${end.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}`;return}if(b.matches('[data-plan-filter]')){document.querySelectorAll('[data-plan-filter]').forEach(x=>x.classList.toggle('active',x===b));const filter=b.dataset.planFilter;document.querySelectorAll('.planner-day').forEach(x=>x.classList.toggle('hidden',filter!=='all'&&x.dataset.status!==filter));return}if(b.classList.contains('planner-action')){const card=b.closest('.planner-day');if(card.dataset.status==='scheduled'){card.dataset.status='published';card.querySelector('.badge').textContent='Published';card.querySelector('.badge').classList.remove('watch');b.textContent='View'}else if(card.dataset.status==='draft'){const title=prompt('Edit content title:',card.querySelector('.planner-post b').textContent);if(title)card.querySelector('.planner-post b').textContent=title}return}if(b.id==='generatePlan'){const goal=document.getElementById('decisionGoal').value,budget=Math.max(100,+document.getElementById('decisionBudget').value||100),product=document.getElementById('decisionProduct').value,chosen=document.getElementById('decisionChannel').value;const best=chosen==='Recommend best channel'?'Instagram':chosen;const objectives={sales:['Drive purchases with a conversion-focused offer','Retarget people who viewed the product but did not purchase','Move 15% of spend from Google to Instagram, which currently leads sales'],awareness:['Lead with a short product story and creator content','Optimize for reach and video completion before retargeting','Use Instagram for broad discovery and LinkedIn for professional proof'],launch:['Warm up the audience with a teaser, then publish the product reveal','Pair launch creative with a limited introductory offer','Use Instagram for discovery and YouTube retargeting for purchase'],retention:['Build a replenishment reminder for recent buyers','Use customer stories and loyalty offers for repeat purchases','Prioritize owned YouTube audiences and retarget engaged social users']}[goal];document.getElementById('decisionOutput').innerHTML=`<div class="decision-brief"><div class="eyebrow">AI GENERATED DECISION BRIEF - SAMPLE DATA</div><h2>${goal==='sales'?'Increase product sales':goal==='awareness'?'Grow brand awareness':goal==='launch'?'Launch a new product':'Bring customers back'}</h2><p>Focus product: <b>${product}</b> - Planned budget: <b>${money(budget)}</b> - Recommended channel: <b>${best}</b></p><div class="decision-actions">${objectives.map((x,i)=>`<div class="decision-action"><span>${String(i+1).padStart(2,'0')}</span><div><b>${x}</b><small>${i===0?'Creative direction':i===1?'Audience & measurement':'Budget allocation'}</small></div></div>`).join('')}</div><div class="decision-kpi"><b>Success measures</b><span>Purchases - Cost per purchase - Revenue vs. target - Conversion rate</span></div><button class="btn" id="sendPlanToPlanner">+ Add a content draft to planner</button></div>`;return}if(b.id==='sendPlanToPlanner'){goto('planner');return}if(b.id==='applyDateRange'){const start=document.getElementById('reportStart').value,end=document.getElementById('reportEnd').value;if(!start||!end||start>end){alert('Choose a valid start and end date.');return}document.getElementById('dateRangeMessage').textContent=`Showing ${new Date(start+'T12:00:00').toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})} - ${new Date(end+'T12:00:00').toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})}`;return}if(b.id==='downloadDateReport'||b.classList.contains('date-export')){const start=document.getElementById('reportStart').value,end=document.getElementById('reportEnd').value;const rows=[['Date range',`${start} to ${end}`],['Channel','Revenue','Purchases','Views','Likes'],...channels.map(c=>[c.name,c.revenue,c.sales,c.views,c.likes])];const csv=rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=`marketwise-report-${start}-to-${end}.csv`;a.click();URL.revokeObjectURL(a.href);return}if(b.id==='datePreset'){return}});
  document.addEventListener('change',e=>{if(e.target.id==='datePreset'&&e.target.value!=='custom'){const days=Number(e.target.value),end=new Date('2026-10-29T12:00:00'),start=new Date(end);start.setDate(start.getDate()-days+1);document.getElementById('reportStart').value=start.toISOString().slice(0,10);document.getElementById('reportEnd').value=end.toISOString().slice(0,10)}});

  pages.settings=()=>`<div class="heading-row"><div><div class="eyebrow">MAKE IT YOURS</div><h1>Settings</h1><p>Update your profile and manage your connected channels.</p></div></div><div class="subnav"><button class="active" data-settings-tab="profile">My profile</button><button data-settings-tab="workspace">Workspace</button><button data-settings-tab="integrations">Integrations</button><button data-settings-tab="notifications">Notifications</button></div><div class="settings-grid"><section class="card panel"><div class="panel-head"><div><h2>Profile details</h2><div class="panel-sub">Your name appears in the workspace navigation.</div></div><span class="spark">JD</span></div><label class="sim-label" for="profileName">Display name</label><input class="decision-input" id="profileName" value="${currentDisplayName().replace(/[&<>"']/g,'') }" maxlength="60" placeholder="Your name"><button class="btn primary" id="saveProfileName" style="margin-top:14px">Save changes</button><div class="setting-row" style="margin-top:16px"><div><b>Login email / username</b><br><span>${(appStorage.getItem('mw-user')||'Demo workspace').replace(/[&<>"']/g,'')}</span></div></div><div class="setting-row"><div><b>Account session</b><br><span>This device</span></div><button class="btn logout-btn" id="logoutButton">Log out</button></div></section><section class="card panel appearance-panel"><div class="panel-head"><div><h2>Appearance</h2><div class="panel-sub">Choose a day or night theme.</div></div></div><div class="theme-options"><button class="theme-option" data-theme-choice="light"><span class="theme-preview light-preview"><i></i><i></i><i></i></span><span><b>Light mode</b><small>Day theme · bright workspace</small></span><span class="theme-check">✓</span></button><button class="theme-option" data-theme-choice="dark"><span class="theme-preview dark-preview"><i></i><i></i><i></i></span><span><b>Dark mode</b><small>Night theme · darker workspace</small></span><span class="theme-check">✓</span></button></div></section><section class="card panel settings-channels"><div class="panel-head"><div><h2>Connected channels</h2><div class="panel-sub">Current reporting sources</div></div></div>${channels.map(c=>`<div class="setting-row"><div style="display:flex;align-items:center;gap:9px"><span class="channel-mark ${c.class}">${c.mark}</span><div><b>${c.name}</b><br><span>Sample data connected</span></div></div><span class="badge">Connected</span></div>`).join('')}<p class="sim-disclaimer">Live account connections can be added when integrations are configured.</p></section></div>`;
  document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='saveProfileName'){const input=document.getElementById('profileName'),name=input.value.trim();if(!name){input.focus();input.setCustomValidity('Please enter your name.');input.reportValidity();return}appStorage.setItem('mw-display-name',name);render();return}if(b.id==='logoutButton'){document.getElementById('app').classList.add('hidden');document.getElementById('auth').classList.remove('hidden');document.getElementById('password').value='';document.getElementById('authForm').reset();const saved=appStorage.getItem('mw-user');if(saved)document.getElementById('username').value=saved;return}if(b.dataset.settingsTab){document.querySelectorAll('[data-settings-tab]').forEach(x=>x.classList.toggle('active',x===b));return}});

  const savedTheme=appStorage.getItem('mw-theme')||'light';window.setMarketwiseTheme=function(theme){if(theme!=='light'&&theme!=='dark')return;document.documentElement.dataset.theme=theme;if(document.body){document.body.dataset.theme=theme;document.body.classList.toggle('dark-mode',theme==='dark')}appStorage.setItem('mw-theme',theme);document.querySelectorAll('[data-theme-choice]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.themeChoice===theme)))};window.setMarketwiseTheme(savedTheme);

  pages.settings=()=>`<div class="heading-row"><div><div class="eyebrow">PERSONALIZE YOUR WORKSPACE</div><h1>Settings</h1><p>Manage your profile, appearance, and connected channels.</p></div></div><div class="subnav"><button class="active" data-settings-tab="profile">My profile</button><button data-settings-tab="workspace">Workspace</button><button data-settings-tab="integrations">Integrations</button><button data-settings-tab="notifications">Notifications</button></div><div class="settings-grid"><section class="card panel"><div class="panel-head"><div><h2>Profile details</h2><div class="panel-sub">Your name appears in the workspace navigation.</div></div></div><label class="sim-label" for="profileName">Display name</label><input class="decision-input" id="profileName" value="${currentDisplayName().replace(/[&<>"']/g,'')}" maxlength="60" placeholder="Your name"><button class="btn primary" id="saveProfileName" style="margin-top:14px">Save changes</button><div class="setting-row" style="margin-top:16px"><div><b>Login email / username</b><br><span>${(appStorage.getItem('mw-user')||'Demo workspace').replace(/[&<>"']/g,'')}</span></div></div><div class="setting-row"><div><b>Account session</b><br><span>This device</span></div><button class="btn logout-btn" id="logoutButton">Log out</button></div></section><section class="card panel appearance-panel"><div class="panel-head"><div><h2>Appearance</h2><div class="panel-sub">Choose how Marketwise looks on this device.</div></div><span class="spark">*</span></div><div class="theme-options"><button class="theme-option" data-theme-choice="light"><span class="theme-preview light-preview"><i></i><i></i><i></i></span><span><b>Light mode</b><small>Bright workspace for daytime</small></span><span class="theme-check">?</span></button><button class="theme-option" data-theme-choice="dark"><span class="theme-preview dark-preview"><i></i><i></i><i></i></span><span><b>Dark mode</b><small>Easy-on-the-eyes dark colors</small></span><span class="theme-check">?</span></button></div></section><section class="card panel settings-channels"><div class="panel-head"><div><h2>Connected channels</h2><div class="panel-sub">Current reporting sources</div></div></div>${channels.map(c=>`<div class="setting-row"><div style="display:flex;align-items:center;gap:9px"><span class="channel-mark ${c.class}">${c.mark}</span><div><b>${c.name}</b><br><span>Sample data connected</span></div></div><span class="badge">Connected</span></div>`).join('')}<p class="sim-disclaimer">Live account connections can be added when integrations are configured.</p></section></div>`;
  document.addEventListener('click',e=>{const choice=e.target.closest('[data-theme-choice]');if(!choice)return;const theme=choice.dataset.themeChoice;window.setMarketwiseTheme(theme);render();document.querySelectorAll('[data-theme-choice]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.themeChoice===theme)))});

  document.addEventListener('click',e=>{const tab=e.target.closest('[data-settings-tab]');if(tab){const grid=document.querySelector('.settings-grid');if(!grid)return;const panels=[...grid.children];let workspace=grid.querySelector('.workspace-settings');if(!workspace){workspace=document.createElement('section');workspace.className='card panel workspace-settings';workspace.innerHTML='<div class="panel-head"><div><h2>Workspace preferences</h2><div class="panel-sub">Manage your team workspace details.</div></div></div><label class="sim-label" for="workspaceName">Workspace name</label><input class="decision-input" id="workspaceName" maxlength="60" value="'+(appStorage.getItem('mw-workspace-name')||'Northstar Studio').replace(/[&<>"']/g,'')+'"><label class="sim-label" for="workspaceCurrency">Reporting currency</label><select class="select decision-input" id="workspaceCurrency"><option>USD - US Dollar</option><option>INR - Indian Rupee</option><option>EUR - Euro</option><option>GBP - British Pound</option></select><button class="btn primary" id="saveWorkspace" style="margin-top:14px">Save workspace</button>';grid.append(workspace);panels.push(workspace)}const mode=tab.dataset.settingsTab;panels.forEach((panel,i)=>panel.classList.toggle('hidden',mode==='profile'?i===2||i===3:mode==='integrations'?i!==2:i!==3));document.querySelectorAll('[data-settings-tab]').forEach(x=>x.classList.toggle('active',x===tab));return}if(e.target.closest('#saveWorkspace')){const name=document.getElementById('workspaceName').value.trim();if(!name){document.getElementById('workspaceName').focus();return}appStorage.setItem('mw-workspace-name',name);const label=document.querySelector('.workspace b');if(label)label.textContent=name;const btn=document.getElementById('saveWorkspace');btn.textContent='? Saved';setTimeout(()=>{if(btn.isConnected)btn.textContent='Save workspace'},1300);return}});
  

  document.addEventListener('click',e=>{const tab=e.target.closest('[data-settings-tab]');if(!tab)return;const grid=document.querySelector('.settings-grid');if(!grid)return;let notification=grid.querySelector('.notification-settings');if(!notification){const getFlag=(key,def)=>appStorage.getItem(key)===null?def:appStorage.getItem(key)==='true';notification=document.createElement('section');notification.className='card panel notification-settings';notification.innerHTML='<div class="panel-head"><div><h2>Notification preferences</h2><div class="panel-sub">Choose which updates you want to see.</div></div></div><label class="notify-option"><span><b>Goal alerts</b><small>When a target is reached or at risk</small></span><input type="checkbox" data-notify="goal" '+(getFlag('mw-notify-goal',true)?'checked':'')+'></label><label class="notify-option"><span><b>Campaign updates</b><small>Changes to scheduled and active campaigns</small></span><input type="checkbox" data-notify="campaign" '+(getFlag('mw-notify-campaign',true)?'checked':'')+'></label><label class="notify-option"><span><b>Weekly report</b><small>A weekly summary of channel performance</small></span><input type="checkbox" data-notify="weekly" '+(getFlag('mw-notify-weekly',false)?'checked':'')+'></label><p class="sim-disclaimer" id="notifySaved">Changes save automatically.</p>';grid.append(notification)}const panels=[...grid.children],mode=tab.dataset.settingsTab;panels.forEach(panel=>{const show=mode==='profile'?(panel===panels[0]||panel.classList.contains('appearance-panel')):mode==='workspace'?panel.classList.contains('workspace-settings'):mode==='integrations'?panel.classList.contains('settings-channels'):panel.classList.contains('notification-settings');panel.classList.toggle('hidden',!show)});document.querySelectorAll('[data-settings-tab]').forEach(x=>x.classList.toggle('active',x===tab))});
  document.addEventListener('change',e=>{const input=e.target.closest('[data-notify]');if(!input)return;appStorage.setItem('mw-notify-'+input.dataset.notify,input.checked);const status=document.getElementById('notifySaved');if(status)status.textContent='Preferences saved.'});
  pages.profile=()=>`<div class="heading-row"><div><div class="eyebrow">YOUR ACCOUNT</div><h1>Profile</h1><p>Manage your name and account details.</p></div></div><section class="card panel profile-settings-card"><div class="profile-large">${currentDisplayName().split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase()}</div><label class="sim-label" for="profileName">Display name</label><input class="decision-input" id="profileName" value="${currentDisplayName().replace(/[&<>"']/g,'')}" maxlength="60" autocomplete="name"><div class="profile-actions"><button class="btn primary" id="saveProfileName">Save changes</button><button class="btn" id="cancelProfileEdit">Cancel</button></div><div class="setting-row"><div><b>Username or email</b><br><span>${(appStorage.getItem('mw-user')||'Demo workspace').replace(/[&<>"']/g,'')}</span></div></div></section>`;titles.profile='Profile';
  function closeProfileMenu(){const menu=document.getElementById('profileMenu'),button=document.getElementById('profileShortcut');if(menu)menu.classList.add('hidden');if(button)button.setAttribute('aria-expanded','false')}
  function toggleProfileMenu(){const menu=document.getElementById('profileMenu'),button=document.getElementById('profileShortcut');if(!menu||!button)return;const opening=menu.classList.contains('hidden');menu.classList.toggle('hidden',!opening);button.setAttribute('aria-expanded',String(opening));if(opening)menu.querySelector('button')?.focus()}
  const profileShortcut=document.getElementById('profileShortcut');if(profileShortcut)profileShortcut.addEventListener('click',e=>{e.stopPropagation();toggleProfileMenu()});
  const sidebarProfile=document.querySelector('.profile');if(sidebarProfile){sidebarProfile.addEventListener('click',()=>goto('profile'));sidebarProfile.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();goto('profile')}})}
  const workspaceButton=document.getElementById('workspaceButton');if(workspaceButton){const openWorkspace=()=>{goto('settings');setTimeout(()=>document.querySelector('[data-settings-tab="workspace"]')?.click(),0)};workspaceButton.addEventListener('click',openWorkspace);workspaceButton.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openWorkspace()}});window.marketwiseOpenSettings=openWorkspace}
  document.addEventListener('click',e=>{const action=e.target.closest('[data-profile-action]');if(action){const which=action.dataset.profileAction;closeProfileMenu();if(which==='profile')goto('profile');else if(which==='settings')goto('settings');else if(which==='logout'){document.getElementById('app').classList.add('hidden');document.getElementById('auth').classList.remove('hidden');document.getElementById('password').value='';document.getElementById('authForm').reset();if(appStorage.getItem('mw-user'))document.getElementById('username').value=appStorage.getItem('mw-user')}return}if(!e.target.closest('.profile-area'))closeProfileMenu();if(e.target.closest('#helpButton')){openUtility('help');return}if(e.target.closest('#notificationsButton')){openUtility('notifications');return}if(e.target.closest('#closeUtility')||e.target.id==='utilityOverlay'){closeUtility();return}if(e.target.closest('#cancelProfileEdit')){goto('overview');return}});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeProfileMenu();closeUtility()} });
  function openUtility(type){const overlay=document.getElementById('utilityOverlay'),body=document.getElementById('utilityContent');if(!overlay||!body)return;if(type==='help'){body.innerHTML='<div class="eyebrow">MARKETWISE HELP</div><h2 id="utilityTitle">How can we help?</h2><p>Choose a workspace section to continue.</p><div class="utility-links"><button class="btn" data-page="overview">Overview</button><button class="btn" data-page="campaigns">Campaigns</button><button class="btn" data-page="goals">Goals &amp; targets</button><button class="btn" data-page="settings">Settings</button></div><p class="sim-disclaimer">This prototype uses sample data and local browser storage.</p>'}else{body.innerHTML='<div class="eyebrow">LATEST UPDATES</div><h2 id="utilityTitle">Notifications</h2><div class="notification-item"><b>Monthly goal is 72% complete</b><p>There are 12 days left in the sample reporting period.</p></div><div class="notification-item"><b>Instagram is your top channel</b><p>Revenue is up 26.2% compared with the previous period.</p></div><button class="btn" id="markNotificationsRead">Mark all as read</button>'}overlay.classList.remove('hidden');overlay.setAttribute('aria-hidden','false');document.getElementById('closeUtility').focus()}
  function closeUtility(){const overlay=document.getElementById('utilityOverlay');if(overlay){overlay.classList.add('hidden');overlay.setAttribute('aria-hidden','true')}}
  document.addEventListener('click',e=>{const route=e.target.closest('#utilityContent [data-page]');if(route){closeUtility();goto(route.dataset.page);return}if(e.target.closest('#markNotificationsRead')){const dot=document.querySelector('.notification-dot');if(dot)dot.style.display='none';e.target.closest('button').textContent='All caught up';return}});
